{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C50", "C56", "C60", "C62", "C65", "C66", "C69", "C71", "C72", "C76", "C77", "C79"],
  "contradictory_card_ids": ["C35"],
  "prediction_basis_card_ids": ["C56", "C60", "C62", "C65", "C66", "C69", "C71", "C72", "C76", "C77", "C79"],
  "claims": [
    {
      "claim": "The query is a fully ionized carboxylic acid at physiological pH with a very low logD (-0.75), and L4/L5 records show that acidic low-logD drugs such as PGE2 and pravastatin have low-to-moderate permeability and undergo efflux, supporting poor passive absorption for the query.",
      "card_ids": ["C50", "C56", "C65"]
    },
    {
      "claim": "L5 shows that 10G has incomplete mass balance in Caco-2 suggestive of intestinal metabolism, and masking a free carboxylic acid as an ester increases absorptive flux, directly illustrating the presystemic-loss liability of the query's free acid and low logD.",
      "card_ids": ["C60", "C62", "C66"]
    },
    {
      "claim": "L6 shows that pravastatin, an acidic low-logD drug, has substantial hepatic clearance (CLh 24.1 mL/min; CLint 6.9-11 mL/min/g liver), and that acidic drugs such as lovastatin acid and 6-gingerol undergo UGT-mediated metabolism, supporting hepatic first-pass loss for the query.",
      "card_ids": ["C69", "C71", "C72", "C76", "C77", "C79"]
    },
    {
      "claim": "The cicaprost high-oral-bioavailability record (C35) is for a different prostacyclin analog and does not overcome the query-specific physicochemical and mechanistic presystemic-loss liabilities.",
      "card_ids": ["C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C69", "C71", "C72", "C76", "C77", "C79"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or matched oral/IV AUC measurement for the query.",
    "No query-specific permeability, efflux, intestinal metabolism, or hepatic clearance measurement; L5/L6 records are for pravastatin, 10G, 6-gingerol, and other molecules.",
    "Transferability of pravastatin/10G/6-gingerol findings to the query is uncertain.",
    "No formulation or prodrug data for the query; oral F may be formulation-dependent.",
    "Possible active uptake transporters (e.g., OATP, MCT) could partially offset low passive permeability."
  ],
  "decision_summary": "Low prediction retained and strengthened: the fully ionized carboxylic acid and low logD predict poor passive permeability, and L5/L6 mechanistic evidence (pravastatin BCRP efflux and hepatic clearance, 10G intestinal metabolism, carboxylic acid masking improving flux) coherently supports presystemic loss. Cicaprost high-F evidence is not query-specific. Confidence is moderate because no direct F measurement exists."
}

